<template>
 <div class="full-check-results">
  <el-alert :type="document.coverage==='OMS_WMS_LIST'?'info':'warning'" :closable="false" :title="document.coverage==='OMS_WMS_LIST'?'覆盖OMS＋人工确认的仓库完整商品清单（导入），不是仓库实时全量枚举':'仅覆盖OMS库存与待处理单据商品清单，尚不能排除仓库独有商品'"/>
  <p class="hint">{{ document.scope.warehouse_list_evidence }}<br>比较虚仓：{{ document.scope.stores.join('、') }}。逐商品取得快照，检查窗口 {{ progress.started_at }} 至 {{ progress.finished_at || '当前' }}，不代表全仓同一时点。</p>
  <div class="progress-box"><b>{{ progress.generated?'商品清单已收集完成':'正在收集商品清单，最终商品总数尚未确定' }}</b><div class="check-metrics"><div><span>{{ progress.generated?'商品总数':'已发现商品' }}</span><strong>{{ progress.total || 0 }} 种</strong></div><div><span>查询成功</span><strong>{{ progress.successful || 0 }} 种</strong></div><div><span>查询失败</span><strong :class="{danger:Number(progress.failed)>0}">{{ progress.failed || 0 }} 种</strong></div><div><span>实物差异 / 字段或冻结待核查</span><strong>{{ document.difference_count }} / {{ document.attention_count }} 行</strong></div></div><el-progress v-if="progress.generated&&Number(progress.total)>0" :percentage="percentage" :show-text="true"/><p v-if="document.state==='COMPLETED'" class="hint">本次清单已查完；仍需按下方结论处理差异、字段缺失和待入账。已查完不等于库存全部一致。</p><p v-if="document.state==='PARTIAL'" class="danger">存在查询失败，当前不具备完整检查结论。缺失结果不会记为0。</p></div>
  <div class="tools"><el-button v-if="['PENDING','RUNNING'].includes(document.state)" v-hasPermi="['warehouse:reconciliation:create']" @click="control('stop')">结束当前商品后停止</el-button><el-button v-if="document.state==='STOPPED'" v-hasPermi="['warehouse:reconciliation:create']" @click="control('resume')">继续未查商品</el-button><el-button v-if="['PARTIAL','FAILED'].includes(document.state)" v-hasPermi="['warehouse:reconciliation:create']" @click="control('retryFailed')">{{ document.state==='FAILED'?'恢复失败任务，保留成功结果':'重试失败，保留成功结果' }}</el-button><span class="hint">后台持续执行，可关闭页面后返回查看。</span></div>
  <h3>商品、批次与质量结果</h3>
  <el-form inline size="small" @submit.native.prevent="search"><el-form-item label="SKU"><el-input v-model.trim="filters.sku_sn" clearable placeholder="完整SKU编码"/></el-form-item><el-form-item label="结论"><el-select v-model="filters.status" @change="search"><el-option label="全部异常（优先查看）" value="ABNORMAL"/><el-option label="全部结果" value=""/><el-option v-for="s in statuses" :key="s" :label="label(s)" :value="s"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button :loading="exporting" @click="exportRows">导出当前筛选</el-button></el-form-item></el-form>
  <p class="hint">共 {{ total }} 行。差额 = WMS实物 − OMS实物；未知不参与差额。复查仅处理勾选商品，最多100种，形成新的库存快照。</p>
  <el-button v-hasPermi="['warehouse:reconciliation:create']" type="primary" size="small" :disabled="!selected.length||saving" @click="recheck">为已选 {{ selected.length }} 种商品创建最新复查</el-button>
  <el-table ref="results" v-loading="loading" :data="rows" size="small" row-key="result_id" empty-text="当前筛选暂无结果；可切换全部结果，或等待后台检查" @selection-change="selection">
   <el-table-column type="selection" width="45"/>
   <el-table-column label="商品 / SKU · 批次 / 质量" min-width="250"><template slot-scope="{row}"><b>{{ row.goods_name || row.sku_sn }}</b><div>{{ row.sku_sn }}</div><div class="hint">{{ row.batch_code || '批次未返回' }} · {{ grade(row.inventory_type) }} · {{ row.stock_unit || '单位待确认' }}</div></template></el-table-column>
   <el-table-column label="实物数量" min-width="160"><template slot-scope="{row}">OMS {{ value(row.oms_physical) }}<br>WMS {{ value(row.wms_physical) }}<div :class="{danger:Number(row.difference)!==0}">差额 {{ signed(row.difference) }}</div></template></el-table-column>
   <el-table-column label="占用与冻结（独立核查）" min-width="180"><template slot-scope="{row}">OMS业务占用 {{ value(row.oms_held) }}<br>WMS冻结 {{ value(row.wms_frozen) }}</template></el-table-column>
   <el-table-column label="结论 / 下一步" min-width="300"><template slot-scope="{row}"><b :class="{danger:row.status!=='MATCHED'}">{{ label(row.status) }}</b><p v-if="row.error" class="danger">{{ row.error }}</p><div v-for="p in row.pending_documents||[]" :key="p.document_sn" class="hint">{{ p.document_sn }}：{{ p.reason }}</div><div class="hint">{{ advice(row.status) }}</div><el-button type="text" @click="$emit('snapshot',row.child_id)">查看该商品快照、虚仓来源与仓库交互</el-button></template></el-table-column>
  </el-table><pagination v-show="total>0" :total="total" :page.sync="filters.pageNum" :limit.sync="filters.pageSize" :page-sizes="[20,50,100]" @pagination="load"/>
 </div>
</template>
<script>
import * as api from '@/api/purchase/warehouseControl'
import {checkLabels,quantity,signed} from '@/utils/inventoryCheck'
export default {props:{document:{type:Object,required:true}},data:()=>({filters:{sku_sn:'',status:'ABNORMAL',pageNum:1,pageSize:20},rows:[],total:0,selected:[],loading:false,saving:false,exporting:false,sequence:0,statuses:['PHYSICAL_DIFFERENCE','WAITING_POST','FROZEN_CHECK','QUERY_FAILED','MISSING_WMS','MISSING_FIELDS','MISSING_BATCH','UNSUPPORTED_TYPE','MATCHED']}),computed:{progress(){return this.document.progress||{}},percentage(){return Math.min(100,Math.floor((Number(this.progress.successful||0)+Number(this.progress.failed||0))/Number(this.progress.total)*100))}},watch:{'document.id'(){this.filters.pageNum=1;this.load()},'document.progress.result_rows'(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++},methods:{label(v){return checkLabels[v]||v},value:quantity,signed,grade(v){return {ZP:'正品',CP:'次品',CC:'次品'}[v]||'质量待确认'},advice(v){return {QUERY_FAILED:'修复查询原因后重试失败商品；未知数量不能当作零。',MISSING_WMS:'核实仓库清单和查询返回范围；未返回不等于零。',PHYSICAL_DIFFERENCE:'核实真实实物与待入账，选中商品创建最新复查后再申请调整。',WAITING_POST:'先核实待确认或待入账单据，再复查最新库存。',FROZEN_CHECK:'核实业务占用和仓库冻结来源，避免按实物盘亏处理。',MISSING_BATCH:'请仓库补齐批次后重新复查。',MISSING_FIELDS:'请仓库补齐未冻结及冻结数量后重新复查。',UNSUPPORTED_TYPE:'需确认原质量类型，不自动归为正品或次品。',MATCHED:'该商品本次快照实物一致，后续业务仍以实时库存为准。'}[v]},search(){this.filters.pageNum=1;this.load()},async load(){const seq=++this.sequence;this.loading=true;try{const r=(await api.checkResults(this.document.id,this.filters)).data;if(seq===this.sequence){this.rows=r.rows||[];this.total=Number(r.total);this.selected=[]}}finally{if(seq===this.sequence)this.loading=false}},selection(rows){this.selected=[...new Set(rows.map(r=>r.sku_sn))]},async control(action){this.saving=true;try{await api.checkControl(this.document.id,action);this.$emit('refresh')}finally{this.saving=false}},async recheck(){this.saving=true;try{const id=(await api.checkRecheck(this.document.id,{request_key:'RECHECK_'+Date.now()+'_'+Math.random().toString(36).slice(2),skus:this.selected})).data;this.$emit('snapshot',id)}finally{this.saving=false}},async exportRows(){this.exporting=true;try{const blob=await api.checkExport(this.document.id,this.filters);if(blob.type&&blob.type.includes('application/json')){const error=JSON.parse(await blob.text());this.$message.error(error.msg||'导出失败，请缩小筛选范围重试');return}const url=URL.createObjectURL(new Blob(['\uFEFF',blob],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=this.document.document_sn+'-检查结果.csv';a.click();URL.revokeObjectURL(url)}finally{this.exporting=false}}}}
</script>
<style scoped>.hint{font-size:13px;color:#74849a;line-height:1.8}.progress-box{border:1px solid #dce5f1;padding:20px;border-radius:8px;margin-top:20px}.check-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:20px 0}.check-metrics span,.check-metrics strong{display:block}.check-metrics span{font-size:13px;color:#74849a;margin-bottom:12px}.check-metrics strong{font-size:22px}.tools{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:18px 0}.danger{color:#c84444}.el-table{margin-top:16px}.full-check-results ::v-deep .cell{overflow-wrap:anywhere}</style>
